CREATE OR REPLACE FUNCTION "public"."app_can_read"() RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$ SELECT public.app_user_role() IN ('reader', 'full', 'admin'); $$;

CREATE OR REPLACE FUNCTION "public"."app_can_write"() RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$ SELECT public.app_user_role() IN ('full', 'admin'); $$;

CREATE OR REPLACE FUNCTION "public"."app_is_admin"() RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$ SELECT public.app_user_role() = 'admin'; $$;

CREATE OR REPLACE FUNCTION "public"."app_user_role"() RETURNS "text"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  SELECT CASE
    WHEN NULLIF(current_setting('app.user_email', true), '') = 'revenueautomationlab@gmail.com' THEN 'admin'
    ELSE (SELECT role FROM public.app_users WHERE email = NULLIF(current_setting('app.user_email', true), '') AND status = 'active')
  END;
$$;

CREATE OR REPLACE FUNCTION "public"."audit_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_actor TEXT := COALESCE(NULLIF(current_setting('app.user_email', true), ''), current_user);
  v_old JSONB := CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END;
  v_new JSONB := CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END;
  v_id TEXT := COALESCE(v_new ->> 'id', v_old ->> 'id');
BEGIN
  INSERT INTO public.audit_log(table_name, row_id, action, actor_email, old_data, new_data)
  VALUES (TG_TABLE_NAME, v_id, TG_OP, v_actor, v_old, v_new);
  RETURN NULL;
END $$;

CREATE OR REPLACE FUNCTION "public"."restore_snapshot"("p_snapshot_id" bigint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  snap JSONB;
  t TEXT;
  i INT;
  tables TEXT[] := ARRAY[
    'payment_schedule_payments','recurring_revenue_payments','recurring_expense_payments',
    'budget_spending','payments','expenses','domains',
    'payment_schedule','recurring_revenue','recurring_expenses',
    'bank_spending','secret_investment_spending','partner_withdrawals','partner_dividends',
    'budgets','projects'
  ];
BEGIN
  SELECT data INTO snap FROM db_snapshots WHERE id = p_snapshot_id;
  IF snap IS NULL THEN RAISE EXCEPTION 'snapshot % not found', p_snapshot_id; END IF;

  FOREACH t IN ARRAY tables LOOP
    EXECUTE format('DELETE FROM public.%I WHERE true', t);
  END LOOP;

  FOR i IN REVERSE array_length(tables, 1)..1 LOOP
    t := tables[i];
    EXECUTE format('INSERT INTO public.%I SELECT * FROM jsonb_populate_recordset(NULL::public.%I, $1->%L)', t, t, t) USING snap;
  END LOOP;
END $_$;

